SELECT DATE(DATE_ADD(started_at, INTERVAL 9 HOUR)) AS day
FROM score_views
WHERE user_id = #{userId} AND started_at < #{to}
GROUP BY day
HAVING SUM(counted_seconds) >= #{minSeconds}
ORDER BY day DESC

